import { inject, injectable } from 'inversify';
import { VimOsBffGraphQLClient } from '../vimOsBffGqlClient';
import { GET_APPLICATION_QUERY } from './queries';
import { GetApplicationResponse, RecordUserAppActivationResponse } from './types';
import { RECORD_USER_APP_ACTIVATION_MUTATION } from './mutations';

@injectable()
export class ApplicationAPI {
  constructor(@inject(VimOsBffGraphQLClient) private gqlClient: VimOsBffGraphQLClient) {}

  public async getApplication(appId: string) {
    const result = await this.gqlClient.queryAuthenticated<
      GetApplicationResponse,
      { appId: string }
    >({
      query: GET_APPLICATION_QUERY(),
      variables: { appId },
    });
    return result.data.application;
  }

  public async recordUserAppActivation(appId: string) {
    const result = await this.gqlClient.mutateAuthenticated<
      RecordUserAppActivationResponse,
      { appId: string }
    >({
      mutation: RECORD_USER_APP_ACTIVATION_MUTATION(),
      variables: { appId },
    });
    return result.data?.recordUserAppActivation;
  }
}
