import { createSlice } from '@reduxjs/toolkit';
import { PayloadAction } from '..';
import { LoginState } from '@/login/types';

export interface LoginSignupSession {
  id: string;
  appId: string;
  appName: string;
}

export type SignupDataOnFailedLogin = {
  newSignupLink: string;
  organizationName?: string;
};

export type LoginFailureReason = 'ORGANIZATION_NOT_FOUND' | 'UNAUTHORIZED_USER';

export type Login = {
  loginState: LoginState | undefined;
  ehrUser: string | undefined;
  signupSession: LoginSignupSession | undefined;
  isSignupFailed: boolean;
  signupDataOnFailedLogin: SignupDataOnFailedLogin | undefined;
  loginFailureReason: LoginFailureReason | undefined;
};

export const initialState: Login = {
  loginState: undefined,
  ehrUser: undefined,
  signupSession: undefined,
  isSignupFailed: false,
  signupDataOnFailedLogin: undefined,
  loginFailureReason: undefined,
};

export const slice = createSlice({
  name: 'login',
  initialState,
  reducers: {
    setEhrUser: (state, action: PayloadAction<Login['ehrUser']>) => {
      state.ehrUser = action.payload;
    },
    setLoginState: (state, action: PayloadAction<Login['loginState']>) => {
      state.loginState = action.payload;
    },
    setSignupSession: (state, action: PayloadAction<Login['signupSession']>) => {
      state.signupSession = action.payload;
    },
    setIsSignupFailed: (state, action: PayloadAction<Login['isSignupFailed']>) => {
      state.isSignupFailed = action.payload;
    },
    setSignupDataForFailedLogin: (
      state,
      action: PayloadAction<SignupDataOnFailedLogin | undefined>,
    ) => {
      state.signupDataOnFailedLogin = action.payload;
    },
    setLoginFailureReason: (state, action: PayloadAction<LoginFailureReason | undefined>) => {
      state.loginFailureReason = action.payload;
    },
  },
});

export const actions = slice.actions;

export default slice.reducer;
