import { gql } from '@getvim-os/gql-client';

export const GET_ORGANIZATION_DETAILS_WITH_TAG_QUERY = gql`
  query getDeviceOrganizationDetailsQuery($input: OrganizationDataOnDevice!) {
    getDeviceOrganizationDetails(input: $input) {
      organizationId
      organizationKey
      organizationName
      organizationTag
      organizationEhrSystem
    }
  }
`;

export const GET_VC_USER_LOGIN_DATA_QUERY = gql`
  query getVCUserLoginDataQuery($input: GetVCUserLoginDataInput!) {
    getVCUserLoginData(input: $input) {
      organizationData {
        organizationId
        organizationKey
        organizationName
        organizationTag
        organizationEhrSystem
      }
    }
  }
`;
