import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { ConsoleUser } from './consoleUser.types';
import { ExternalRole } from '@getvim-os/types';

export const initialState: ConsoleUser = {
  externalRoles: undefined,
};

export const slice = createSlice({
  name: 'consoleUser',
  initialState,
  reducers: {
    setExternalRoles: (state, action: PayloadAction<ExternalRole[] | undefined>) => {
      state.externalRoles = action.payload
        ? action.payload.reduce((acc, role) => {
            acc[role] = true;
            return acc;
          }, {} as Record<ExternalRole, boolean>)
        : undefined;
    },
  },
});

export const actions = slice.actions;

export default slice.reducer;
