import { EntityType, VaultPutResult } from '@/internal-api/vault/types';
import { DIVimTracerProvider } from '@getvim/opentelemetry-sdk/inversify';
import { EHRResource } from '@getvim-os/types';
import { inject, injectable } from 'inversify';
import { v4 as uuid } from 'uuid';
import { EhrPIIRemover } from '../ehrPIIRemover';
import { PendingEhrState } from '../types';
import { VaultManager } from './vault.service';
import { OsFeatureFlagsClient } from '@/infra/featureFlags';

@injectable()
export class VaultTokenizerService {
  private tokensCache: Record<
    string,
    {
      content: string;
      token: string;
    }
  > = {};

  constructor(
    @inject(EhrPIIRemover) private ehrPIIRemover: EhrPIIRemover,
    @inject(VaultManager) private vaultManager: VaultManager,
    @inject(DIVimTracerProvider) private traceProvider: DIVimTracerProvider,
    @inject(OsFeatureFlagsClient) private ffClient: OsFeatureFlagsClient,
  ) {}

  public async generateEntitiesTokens(
    pendingEhrState: PendingEhrState,
    requestedEHRResources: { patient?: boolean; encounter?: boolean; referral?: boolean },
    abortSignal?: AbortSignal,
  ): Promise<VaultPutResult> {
    const shouldOnlyTokenizeEhrResources = await this.ffClient.getFlag({
      flagName: 'shouldOnlyTokenizeEhrResources',
      defaultValue: false,
    });

    const tracer = this.traceProvider.getTracer('tokenize-entities');
    return await tracer.startAutoRootSpan('entities-tokenize-logic', {}, async (rootSpan) => {
      const tokens: VaultPutResult = {};
      const entitiesToTokenize: {
        [key in EHRResource]?: { id: any; entityType: EntityType };
      } = {};

      if (
        pendingEhrState.patient &&
        (requestedEHRResources?.patient || !shouldOnlyTokenizeEhrResources)
      ) {
        const [_, { patientId, ...patientPii }] = this.ehrPIIRemover.removePatientPII(
          pendingEhrState.patient,
        );

        const vaultPayload = {
          id: patientId,
          entityType: EntityType.PATIENT,
          ...patientPii,
        };

        this.processVaultPayload(vaultPayload, tokens, entitiesToTokenize, EHRResource.patient);
      }
      if (
        pendingEhrState.referral &&
        (requestedEHRResources?.referral || !shouldOnlyTokenizeEhrResources)
      ) {
        const [cleanReferral, referralPii] = this.ehrPIIRemover.removeReferralPII(
          pendingEhrState.referral,
        );

        const vaultPayload = {
          id: cleanReferral.vimReferralId ?? uuid(),
          entityType: EntityType.REFERRAL,
          ...referralPii,
        };

        this.processVaultPayload(vaultPayload, tokens, entitiesToTokenize, EHRResource.referral);
      }
      if (
        pendingEhrState.encounter &&
        (requestedEHRResources?.encounter || !shouldOnlyTokenizeEhrResources)
      ) {
        const [cleanEncounter, encounterPii] = this.ehrPIIRemover.removeEncounterPII(
          pendingEhrState.encounter,
        );

        const vaultPayload = {
          id: cleanEncounter.encounterId ?? uuid(),
          entityType: EntityType.ENCOUNTER,
          ...encounterPii,
        };

        this.processVaultPayload(vaultPayload, tokens, entitiesToTokenize, EHRResource.encounter);
      }

      const sensitiveDataForVault = Object.values(entitiesToTokenize).map(
        ({ entityType, ...sensitiveData }) => ({
          entityType,
          sensitiveData,
        }),
      );

      const results =
        sensitiveDataForVault.length > 0
          ? await rootSpan.startAutoChildSpan(
              'put sensitive data in vault',
              { attributes: { entities: Object.keys(entitiesToTokenize) } },
              async (childSpan) =>
                await this.vaultManager.putSensitiveDataInVault(
                  sensitiveDataForVault,
                  abortSignal,
                  childSpan,
                ),
            )
          : {};

      // Update tokens cache with results
      if (entitiesToTokenize.patient && results.patientPut) {
        this.tokensCache[entitiesToTokenize.patient.id] = {
          content: this.encodeEntityPayload(entitiesToTokenize.patient),
          token: results.patientPut,
        };
      }
      if (entitiesToTokenize.referral && results.referralPut) {
        this.tokensCache[entitiesToTokenize.referral.id] = {
          content: this.encodeEntityPayload(entitiesToTokenize.referral),
          token: results.referralPut,
        };
      }
      if (entitiesToTokenize.encounter && results.encounterPut) {
        this.tokensCache[entitiesToTokenize.encounter.id] = {
          content: this.encodeEntityPayload(entitiesToTokenize.encounter),
          token: results.encounterPut,
        };
      }

      return {
        ...tokens,
        ...results,
      };
    });
  }

  private encodeEntityPayload(entity: { id: any }) {
    const uniqueId = window.btoa(encodeURIComponent(JSON.stringify(entity)));
    return uniqueId;
  }

  private processVaultPayload(
    vaultPayload: { id: string; entityType: EntityType; [key: string]: any },
    tokens: VaultPutResult,
    entitiesToTokenize: { [key in EHRResource]?: { id: any; entityType: EntityType } },
    entityKey: EHRResource,
  ): void {
    const content = this.encodeEntityPayload(vaultPayload);
    if (this.tokensCache[vaultPayload.id]?.content === content) {
      tokens[`${entityKey}Put`] = this.tokensCache[vaultPayload.id].token;
    } else {
      entitiesToTokenize[entityKey] = vaultPayload;
    }
  }
}
