import { Logger, LoggerFactory } from '@getvim-os/logger';
import { VimOsGraphQLClient } from '@getvim-os/gql-client';
import { inject, injectable } from 'inversify';
import { OrganizationNotFoundError } from './errors';
import { GET_ORGANIZATION_DETAILS_WITH_TAG_QUERY, GET_VC_USER_LOGIN_DATA_QUERY } from './queries';
import {
  OrganizationDetails,
  OrganizationQueryInput,
  GetVCUserLoginDataInput,
  GetVCUserLoginDataResponse,
} from './types';

@injectable()
export class OrganizationsApi {
  private logger: Logger;

  constructor(
    @inject(VimOsGraphQLClient) private gqlClient: VimOsGraphQLClient,
    @inject(LoggerFactory) loggerFactory: LoggerFactory,
  ) {
    this.logger = loggerFactory.create('Organization-API');
  }

  getDeviceOrganizationDetails = async (
    orgDataOnDevice: OrganizationQueryInput,
  ): Promise<OrganizationDetails> => {
    try {
      const { data } = await this.gqlClient.query<
        { getDeviceOrganizationDetails: OrganizationDetails },
        { input: OrganizationQueryInput }
      >({
        query: GET_ORGANIZATION_DETAILS_WITH_TAG_QUERY,
        variables: { input: orgDataOnDevice },
      });

      return data!.getDeviceOrganizationDetails;
    } catch (error) {
      if ((error as Error)?.message?.includes('Request failed with status code 404')) {
        throw new OrganizationNotFoundError({
          orgDataOnDevice,
          error,
        });
      } else {
        this.logger.warning(
          'Failed to get device organization Id',
          {
            orgDataOnDevice,
          },
          error as Error,
        );
        throw error;
      }
    }
  };

  getVCUserLoginData = async (input: GetVCUserLoginDataInput): Promise<OrganizationDetails> => {
    try {
      const { data } = await this.gqlClient.query<{
        getVCUserLoginData: GetVCUserLoginDataResponse;
      }>({
        query: GET_VC_USER_LOGIN_DATA_QUERY,
        variables: { input },
      });

      return data.getVCUserLoginData.organizationData;
    } catch (error) {
      throw new OrganizationNotFoundError({
        input,
        error,
      });
    }
  };
}
