import { gql } from '@getvim-os/gql-client';

export const ACCOUNT_ME_QUERY = () => gql`
  query getAccountMe {
    getAccountMe {
      accountId
      accountName
      accountTypes
    }
  }
`;

export const GET_ACCOUNT_INFO_QUERY = gql`
  query GetAccountInfo {
    getAccountInfo {
      account {
        address
        tin
      }
    }
  }
`;
