import { inject, injectable } from 'inversify';
import { VimOsBffGraphQLClient } from '../vimOsBffGqlClient';
import {
  CanAccessMarketplaceResponse,
  GetMarketplaceApplicationsResponse,
} from './marketplaceApplicationTypes';
import {
  ADD_APPLICATION_QUERY,
  GET_MARKETPLACE_APPLICATIONS_QUERY,
  SUBMIT_REQUEST_FOR_APP,
  USER_CAN_ACCESS_MARKETPLACE_QUERY,
  ADD_APPLICATION_TO_ORGANIZATION_AND_USERS_QUERY,
} from './marketplaceApplicationsQueries';
import { ApplicationManifest } from '@getvim-os/types';

@injectable()
export class MarketPlaceApplicationsAPI {
  constructor(@inject(VimOsBffGraphQLClient) private gqlClient: VimOsBffGraphQLClient) {}

  public async getApplications(): Promise<GetMarketplaceApplicationsResponse> {
    const result = await this.gqlClient.queryAuthenticated<{
      getAllMarketplaceApplications: GetMarketplaceApplicationsResponse;
    }>({
      query: GET_MARKETPLACE_APPLICATIONS_QUERY,
      fetchPolicy: 'no-cache',
    });
    return result.data.getAllMarketplaceApplications;
  }
  public async submitApplicationAccessRequest(
    applicationId: string,
    dataSources: Array<string> | undefined,
  ): Promise<any> {
    const result = await this.gqlClient.mutateAuthenticated<{
      submitRequestForApp: any;
      appId: string;
    }>({
      mutation: SUBMIT_REQUEST_FOR_APP,
      variables: { input: { appId: applicationId, dataSources } },
    });
    return result.data;
  }

  async canAccessMarketPlace(): Promise<boolean> {
    const res = await this.gqlClient.queryAuthenticated<{
      canAccessMarketplace: CanAccessMarketplaceResponse;
    }>({
      query: USER_CAN_ACCESS_MARKETPLACE_QUERY,
    });
    return res.data.canAccessMarketplace.canAccessMarketplace;
  }

  public async addApplication(applicationId: string): Promise<ApplicationManifest | undefined> {
    const result = await this.gqlClient.mutateAuthenticated<{
      addApplication: ApplicationManifest | undefined;
    }>({
      mutation: ADD_APPLICATION_QUERY,
      variables: { input: { appId: applicationId } },
    });
    return result.data?.addApplication;
  }

  public async addApplicationToOrganizationAndUsers(
    applicationId: string,
    allUsers?: boolean,
    userIds?: string[],
  ): Promise<ApplicationManifest | undefined> {
    const result = await this.gqlClient.mutateAuthenticated<{
      addApplicationToOrganizationAndUsers: ApplicationManifest | undefined;
    }>({
      mutation: ADD_APPLICATION_TO_ORGANIZATION_AND_USERS_QUERY,
      variables: { input: { applicationId: applicationId, allUsers, userIds } },
    });
    return result.data?.addApplicationToOrganizationAndUsers;
  }
}
