import { InjectedApplication } from '@/hub/types/application';
import { Logger } from '@getvim-os/logger';

export const getAllowedOrigins = (application: InjectedApplication, logger?: Logger): string[] => {
  const { allowedUrls, url } = application.manifest?.metadata || {};
  if (!allowedUrls && !url) {
    return [];
  }
  try {
    if (allowedUrls) {
      return allowedUrls
        .split(',')
        .map((url) => {
          try {
            const origin = new URL(url.trim()).origin;
            return origin;
          } catch (error) {
            logger?.error('Error extracting allowed origins from allowedUrls', {
              allowedUrls,
              url,
              error,
            });
            return null;
          }
        })
        .filter((url) => !!url) as string[];
    }

    return [new URL(url || '').origin];
  } catch (error) {
    logger?.error('Error extracting allowed origins from allowedUrls', {
      allowedUrls,
      url,
      error,
    });
    return [];
  }
};
