import { Events } from '@deprecated/types';
import { inject, injectable } from 'inversify';
import { OsState } from '..';
import { RuntimeMessageHooks, VIM_OS_EVENTS } from '../../deprecated/runtime-wrapper/messageHooks';
import { BaseStateManager } from '../lib/baseStateManager.service';
import { actions } from './hubState.slice';
import { AuthEvents, WriteBackEvents } from '../../deprecated/types/events';
import { InitializeOnBootstrap } from '../../bootstrap';
import { Logger, LoggerFactory } from '@getvim-os/logger';
import { HorizontalHubPosition } from '@deprecated/types/ui';
@injectable()
export default class HubStateManager extends BaseStateManager implements InitializeOnBootstrap {
  private logger: Logger;
  constructor(
    @inject(OsState) osState: OsState,
    @inject(RuntimeMessageHooks) private messageHooks: RuntimeMessageHooks,
    @inject(LoggerFactory) loggerFactory: LoggerFactory,
  ) {
    super(osState);
    this.logger = loggerFactory.create('HubStateManager');
  }

  get isEmbeddedPanelMode() {
    return HubStateManager.calculateIsEmbeddedPanelMode();
  }
  static calculateIsEmbeddedPanelMode() {
    const searchParams = new URLSearchParams(window.location.search);
    return (
      searchParams.get('embedded-panel-view') === 'true' || searchParams.get('flatView') === 'true'
    );
  }

  public initialize() {
    this.messageHooks.addOSMessageHandler(
      VIM_OS_EVENTS.AUTH_EVENT,
      this.onVimOsAuthEvent.bind(this),
    );
    this.messageHooks.addOSMessageHandler(
      VIM_OS_EVENTS.WRITEBACK_EVENT,
      this.onVimOsWriteBackEvent.bind(this),
    );
  }

  private onVimOsAuthEvent(message: Events.RuntimeToOsMessage[VIM_OS_EVENTS.AUTH_EVENT]) {
    switch (message.type) {
      case AuthEvents.INITIALIZE_ME: {
        if (message.payload.hubPosition) {
          const hubPosition = { ...message.payload.hubPosition };
          if (message.payload.me.ehrUser.organization.ehrSystem === 'practice-fusion') {
            hubPosition.horizontal = HorizontalHubPosition.Left;
          }
          this.store.dispatch(actions.setPosition(hubPosition));
        }
        break;
      }
    }
  }

  private onVimOsWriteBackEvent(message: Events.RuntimeToOsMessage[VIM_OS_EVENTS.WRITEBACK_EVENT]) {
    switch (message.type) {
      case WriteBackEvents.DISPLAY_WRITE_BACK_OVERLAY: {
        this.logger.info('onVimOsWriteBackEvent received overlay display', { message });
        this.store.dispatch(actions.displayWriteBackOverlay(message.payload));
        break;
      }
      case WriteBackEvents.HIDE_WRITE_BACK_OVERLAY: {
        this.logger.info('onVimOsWriteBackEvent received overlay hide', { message });
        this.store.dispatch(actions.hideWriteBackOverlay());
        break;
      }
    }
  }
}
