import { inject, injectable } from 'inversify';
import { VimOsBffGraphQLClient } from '../vimOsBffGqlClient';
import { ACCOUNT_ME_QUERY, GET_ACCOUNT_INFO_QUERY } from './queries';
import { AccountInfoResponse, AccountMeResponse } from './types';

@injectable()
export class AccountAPI {
  constructor(@inject(VimOsBffGraphQLClient) private gqlClient: VimOsBffGraphQLClient) {}

  public async getAccountMe() {
    const result = await this.gqlClient.queryAuthenticated<AccountMeResponse>({
      query: ACCOUNT_ME_QUERY(),
    });
    return result.data.getAccountMe;
  }

  public async getAccountInfo() {
    const result = await this.gqlClient.queryAuthenticated<AccountInfoResponse>({
      query: GET_ACCOUNT_INFO_QUERY,
    });
    return result.data.getAccountInfo;
  }
}
