import { injectable } from 'inversify';
import {
  FinalizeSignupAsyncResDto,
  FinalizeSignupReqDto,
  FinalizeSignupResDto,
  GetSessionResDto,
} from './types';
import { generateAxiosInstance } from '@/internal-api/utility/generateAxiosInstance';
import { handleAxiosError } from '@/internal-api/utility/handleAxiosError';

const axiosInstance = generateAxiosInstance({
  serviceUrlEnvKey: 'VIM_SIGNUP_API_URL',
});

@injectable()
export class SignupApi {
  public finalizeSignup = async ({
    sessionId,
    data,
  }: FinalizeSignupReqDto): Promise<FinalizeSignupResDto> => {
    try {
      const res = await axiosInstance.post<FinalizeSignupResDto>(
        `/v1/application-signup/${sessionId}/finalize`,
        data,
      );
      return res.data;
    } catch (error) {
      handleAxiosError(error, SignupApi.name);
    }
  };

  public finalizeSignupAsync = async ({
    sessionId,
    data,
  }: FinalizeSignupReqDto): Promise<FinalizeSignupAsyncResDto> => {
    try {
      const res = await axiosInstance.post<FinalizeSignupAsyncResDto>(
        `/v1/application-signup/async/${sessionId}/finalize`,
        data,
      );
      return res.data;
    } catch (error) {
      handleAxiosError(error, SignupApi.name);
    }
  };

  public getSignupSession = async (sessionId: string): Promise<GetSessionResDto> => {
    try {
      const res = await axiosInstance.get<GetSessionResDto>(`/v1/application-signup/${sessionId}`);
      return res.data;
    } catch (error) {
      handleAxiosError(error, SignupApi.name);
    }
  };
}
