import { gql } from '@getvim-os/gql-client';

export const GET_MARKETPLACE_APPLICATIONS_QUERY = gql`
  query getMarketplaceApplications {
    getAllMarketplaceApplications {
      applications {
        account {
          name
          address
          phoneNumber
        }
        id
        name
        canAddApplicationDirectly
        submission {
          appStoreListing
          securityAndCompliance
          marketplaceSettings
        }
        isCoreApp
        isPhiFree
        isInstalled
        dataConnections {
          name
          iconUrl
          id
          enum
          connectionType
        }
        manifest {
          metadata {
            name
            services {
              id
              metadata {
                id
                description
                url
              }
              capabilities {
                enrichEHR {
                  allowedPII
                  resources {
                    patient
                    encounter
                    orders
                    referral
                  }
                }
                enrichUser
                custom
                allowedPII
                actions
              }
            }
          }
          session {
            permissions
          }
          UI {
            iconUrl
            capabilities {
              showPatientHeader
              counterNotificationLabel
              popupNotification
              autoPopup
              overridePopupLimit
              appAlwaysAvailable
            }
          }
          EHR {
            resourcePermissions
          }
        }
      }
    }
  }
`;

export const SUBMIT_REQUEST_FOR_APP = gql`
  mutation RequestToAddApplication($input: RequestToAddApplicationInput!) {
    requestToAddApplication(input: $input) {
      success
    }
  }
`;

export const USER_CAN_ACCESS_MARKETPLACE_QUERY = gql`
  query CanAccessMarketPlace {
    canAccessMarketplace {
      canAccessMarketplace
    }
  }
`;

export const ADD_APPLICATION_QUERY = gql`
  mutation AddApplication($input: AddApplicationInput) {
    addApplication(input: $input) {
      version
      metadata {
        id
        url
        allowedUrls
        launchEndpoint
        tokenEndpoint
        name
        services {
          id
          metadata {
            url
          }
          capabilities {
            enrichEHR {
              allowedPII
              resources {
                patient
                encounter
                orders
                referral
              }
            }
            enrichUser
            custom
            actions
          }
        }
      }
      UI {
        tooltip
        icon
        iconUrl
        size
        capabilities {
          showPatientHeader
          counterNotificationLabel
          popupNotification
          autoPopup
          overridePopupLimit
          appAlwaysAvailable
        }
        launchButton {
          ... on ConfigurableLaunchButton {
            irrelevantVisibility
            alt
            primaryColor
            borderColor
            fontColor
            mode {
              small {
                text
                image
              }
              medium {
                text
                image
              }
              large {
                text
                image
              }
            }
          }
          ... on CustomLaunchButton {
            customHTML
          }
        }
      }
      session {
        permissions
      }
      EHR {
        resourcePermissions
        allowedPII
        actions {
          FIND_PATIENT
          GET_PATIENT
          GET_ENCOUNTER_DATA
          GET_PATIENT_ENCOUNTERS
          GET_PROVIDER_DAILY_SUMMARY
          GET_PATIENT_SCHEDULED_APPOINTMENTS
          PRINT_ENCOUNTER
          PRINT_ENCOUNTERS
          GET_ENCOUNTER_LAB_RESULTS
          GET_ENCOUNTER_VITALS
          SEARCH_PROVIDERS
          NAVIGATE_TO_ENCOUNTER
          GET_PROVIDER_APPOINTMENTS
          GET_GAPS_FROM_SHARED_REQUEST
        }
        launchButtonRealEstate {
          referral {
            REFERRAL_SELECT_PROVIDER
          }
          orders {
            DI_SELECT_PROVIDER
            LABS_SELECT_PROVIDER
          }
        }
      }
      auth {
        vimTokens
      }
      vimCapabilities {
        trackAnalytics
      }
    }
  }
`;

