import { injectable } from 'inversify';

import { LinkUserInput, SilentLoginInput, SilentLoginOutput } from './types';

import axiosRetry from 'axios-retry';
import {
  createAxiosInstanceWithTelemetry,
  ApiRequestOptions,
  AxiosInstanceWithTelemetry,
} from '@getvim/opentelemetry-sdk/client';
import { AxiosInstance } from 'axios';

@injectable()
export class SeamlessAuthApi {
  private axiosInstance: AxiosInstanceWithTelemetry;
  constructor() {
    const url = window.$vim_environment?.VIM_SEAMLESS_API_URL as string | undefined;
    const axiosInstance = createAxiosInstanceWithTelemetry({
      baseURL: url,
    });

    axiosRetry(axiosInstance as AxiosInstance, {
      retries: 3,
      retryDelay: (retryCount) => {
        return retryCount * 1000; // Time to wait between retries (1s, 2s, 3s)
      },
    });
    this.axiosInstance = axiosInstance;
  }
  public silentLogin = async (data: SilentLoginInput, { span }: ApiRequestOptions) => {
    const res = await this.axiosInstance.post<SilentLoginOutput>(`/v1/login/silent-login`, data, {
      telemetry: {
        parentSpan: span,
      },
    });
    // Axios lowercases all header names
    const serverTime = res.headers['date'];
    return {
      result: res.data,
      serverTime,
    };
  };

  public addEhrCredentialsIdentity = async (
    data: LinkUserInput,
    accessToken: string,
    { span }: ApiRequestOptions,
  ) => {
    return await this.axiosInstance.post<void>(`/v1/auth/identities/ehr-credentials`, data, {
      headers: {
        Authorization: accessToken,
      },
      telemetry: {
        parentSpan: span,
      },
    });
  };

  public changeEhrCredentialsIdentityPassword = async (
    data: LinkUserInput,
    accessToken: string,
    { span }: ApiRequestOptions,
  ) => {
    return await this.axiosInstance.post<void>(
      `/v1/auth/identities/ehr-credentials/update-password`,
      data,
      {
        headers: {
          Authorization: accessToken,
        },
        telemetry: {
          parentSpan: span,
        },
      },
    );
  };

  public getUserPasswordSalt = async (accessToken: string, { span }: ApiRequestOptions) => {
    const res = await this.axiosInstance.get<{ ehrPasswordSalt: string | undefined }>(
      `/v1/auth/ehr-password-salt`,
      {
        headers: {
          Authorization: accessToken,
        },
        telemetry: {
          parentSpan: span,
        },
      },
    );
    return res.data.ehrPasswordSalt;
  };
}
