import { generateAxiosInstance } from '@/internal-api/utility/generateAxiosInstance';
import { handleAxiosError } from '@/internal-api/utility/handleAxiosError';
import { injectable } from 'inversify';

export interface GetAppStoreApplicationResponse {
  id: string;
  displayName: string;
}

const axiosInstance = generateAxiosInstance({
  serviceUrlEnvKey: 'VIM_CONSOLE_API_URL',
});

@injectable()
export class ConsoleApi {
  async getAppStoreApplication(params: {
    applicationId: string;
  }): Promise<GetAppStoreApplicationResponse> {
    try {
      const { data } = await axiosInstance.get<GetAppStoreApplicationResponse>(
        `/v1/applications/${params.applicationId}`,
      );
      return data;
    } catch (error: any) {
      handleAxiosError(error, ConsoleApi.name);
    }
  }
}
