import { gql } from '@getvim-os/gql-client';

export const UPDATE_ME = gql`
  mutation updateMe($input: UpdateMeFields!) {
    updateMe(input: $input) {
      success
    }
  }
`;

export const GET_ORGANIZATION_USERS = gql`
  query GetVimConnectUsersForOrganization {
    getVimConnectUsersForOrganization {
      count
      users {
        id
        email
        firstName
        lastName
        linkedEhrUser
        products
        roles
      }
    }
  }
`;

export const GET_ORGANIZATION_USERS_COUNT = gql`
  query GetVimConnectUsersForOrganizationCount {
    getVimConnectUsersForOrganization {
      count
    }
  }
`;
