import { inject, injectable } from 'inversify';
import { GET_ORGANIZATION_USERS, GET_ORGANIZATION_USERS_COUNT, UPDATE_ME } from './queries';
import { VimOsBffGraphQLClient } from '../vimOsBffGqlClient';
import { GetOrganizationUsersResponse, UpdateMeInput, UpdateMeResponse } from './types';

@injectable()
export class UserAPI {
  constructor(@inject(VimOsBffGraphQLClient) private gqlClient: VimOsBffGraphQLClient) {}

  public async updateMe(
    input: Pick<UpdateMeInput, 'roles'>,
  ): Promise<UpdateMeResponse | undefined> {
    const result = await this.gqlClient.mutateAuthenticated<
      { updateMe: UpdateMeResponse },
      { input: Pick<UpdateMeInput, 'roles'> }
    >({
      mutation: UPDATE_ME,
      variables: { input },
    });

    return result.data?.updateMe;
  }

  public async getOrganizationUsers(): Promise<GetOrganizationUsersResponse> {
    const result = await this.gqlClient.queryAuthenticated<{
      getVimConnectUsersForOrganization: GetOrganizationUsersResponse;
    }>({
      query: GET_ORGANIZATION_USERS,
      fetchPolicy: 'no-cache',
    });

    return result.data?.getVimConnectUsersForOrganization;
  }

  public async getOrganizationUsersCount(): Promise<{ count: number }> {
    const result = await this.gqlClient.queryAuthenticated<{
      getVimConnectUsersForOrganization: { count: number };
    }>({
      query: GET_ORGANIZATION_USERS_COUNT,
    });

    return result.data?.getVimConnectUsersForOrganization;
  }
}
